export function formatPace(seconds){if(!Number.isFinite(seconds)||seconds<=0)return '—';const s=Math.round(seconds);return Math.floor(s/60)+':'+String(s%60).padStart(2,'0');}
export function resolveRhythm(row){const num=v=>v===''||v===null||v===undefined?null:Number(v);let distance=num(row.distance),minutes=num(row.minutes),pace=null;const text=String(row.pace??'').trim();if(text){const m=text.match(/^(\d{1,3}):([0-5]\d)$/);if(!m)throw new Error('Pace deve usar min:seg por km, como 10:00.');pace=Number(m[1])*60+Number(m[2]);if(pace<=0)throw new Error('Pace deve ser positivo.');}if(distance===null&&minutes===null&&pace===null)return null;for(const v of [distance,minutes])if(v!==null&&(!Number.isFinite(v)||v<=0))throw new Error('Distância e tempo devem ser positivos e finitos.');if([distance,minutes,pace].filter(v=>v!==null).length<2)throw new Error('Informe pelo menos dois valores: km e tempo, km e pace ou tempo e pace.');if(distance===null)distance=minutes*60/pace;if(minutes===null)minutes=distance*pace/60;const calculated=minutes*60/distance;if(pace!==null&&Math.abs(calculated-pace)>1)throw new Error('Pace incompatível com os quilômetros e o tempo. Confira os valores.');if(distance>200||minutes>1440)throw new Error('Confira os limites: até 200 km e 1.440 min por trecho.');return {distance,minutes,speed:distance/minutes*60,paceSeconds:calculated,paceInput:text||null,incline:Number(row.incline||0)};}
export function appendRhythm(container,data={},options={}){const row=document.createElement('div');row.className='entry-row rhythm-row';row.innerHTML='<div class="rhythm-grid"><label>Distância (km)<input data-rhythm="distance" type="number" min="0" max="200" step="any" inputmode="decimal" placeholder="Ex.: 2,4"></label><label>Tempo (min)<input data-rhythm="minutes" type="number" min="0" max="1440" step="any" inputmode="decimal" placeholder="Ex.: 30"></label></div><label>Pace (min:seg/km) <small>opcional</small><input data-rhythm="pace" type="text" inputmode="text" placeholder="Ex.: 12:30" pattern="[0-9]{1,3}:[0-5][0-9]"></label><p class="rhythm-summary helper"></p>';
row.querySelector('[data-rhythm=distance]').value=data.distance??(data.speed&&data.minutes?Math.round(data.speed*data.minutes/60*1000)/1000:'');row.querySelector('[data-rhythm=minutes]').value=data.minutes??'';row.querySelector('[data-rhythm=pace]').value=data.paceInput??'';
if(options.incline){const label=document.createElement('label');label.textContent='Inclinação (%) · opcional';const input=document.createElement('input');input.type='number';input.min=0;input.max=30;input.step='.1';input.dataset.rhythm='incline';input.value=data.incline??0;label.append(input);row.append(label);}
const update=()=>{const summary=row.querySelector('.rhythm-summary');try{const v=resolveRhythm(readRhythm(row));summary.textContent=v?'Pace calculado: '+formatPace(v.paceSeconds)+'/km · '+v.speed.toLocaleString('pt-BR',{maximumFractionDigits:2})+' km/h':'Informe km e tempo; o pace é opcional.';summary.classList.remove('error');}catch(e){summary.textContent=e.message;summary.classList.add('error');}};row.addEventListener('input',update);if(options.removable){const b=document.createElement('button');b.type='button';b.className='remove';b.textContent='Remover trecho';b.onclick=()=>{row.remove();options.onRemove?.();};row.append(b);}container.append(row);update();return row;}
export function readRhythm(row){const read=k=>row.querySelector('[data-rhythm='+k+']')?.value??'';return {distance:read('distance'),minutes:read('minutes'),pace:read('pace'),incline:read('incline')};}
export function readRhythms(container){return Array.from(container.querySelectorAll('.rhythm-row')).map(r=>resolveRhythm(readRhythm(r))).filter(Boolean);}
